assert len(EVALS) == 12
assert len({case['title'] for case in EVALS}) == 12
for case in EVALS:
    assert len(case['concepts']) == len(set(case['concepts'])) == 4
    assert len(case['steps']) == 5
    assert len(case.get('nodes', [])) in (0, 4)
